    VRFW.host.menu_command(B.NODE_TRANSLATION, B.LAYER, 0, B.LINE_DOWN, B.LINE_X, B.LINE_Y + top_edge_shift, 0)
    BetterQoL.combo_partner_card.band_cut = cut
  end

